#include <omp.h>
#include <array>
#include <cstddef>
#include <vector>

using std::size_t;

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (size_t i = 0; i < x.size(); ++i) {
            const double v = x[i];

            int bin = static_cast<int>(v / 10.0);
            if (bin < 0) {
                bin = 0;
            } else if (bin > 9) {
                // Places v == 100.0 into the last bin.
                bin = 9;
            }

            ++local_bins[static_cast<size_t>(bin)];
        }

        for (int b = 0; b < 10; ++b) {
            #pragma omp atomic update
            bins[static_cast<size_t>(b)] += local_bins[static_cast<size_t>(b)];
        }
    }
}
